use verus::prelude::*;

verus! {

    /// Concatenate two read‐only slices of i32, preserving their order.
    ///
    /// Ensures
    /// - The result’s length is the sum of the inputs’ lengths.
    /// - For each index `i` in the first slice, `result[i] == a[i]`.
    /// - For each index `j` in the second slice, `result[a.len() + j] == b[j]`.
    fn concat(a: &[i32], b: &[i32]) -> Vec<i32>
        ensures
            // length is sum of the two inputs
            ret.len() == a.len() + b.len() &&
            // prefix matches `a`
            forall(|i: usize| i < a.len() ==> ret[i] == a[i]) &&
            // suffix matches `b`
            forall(|j: usize| j < b.len() ==> ret[a.len() + j] == b[j])
    {
        // Pre‐allocate
        let mut result: Vec<i32> = Vec::new();
        result.reserve(a.len() + b.len());

        // First loop: copy all of `a`
        let n1 = a.len();
        let mut i: usize = 0;
        while i < n1
            invariant i <= n1;
            invariant result.len() == i;
            invariant forall(|k: usize| k < i ==> result[k] == a[k]);
            decreases n1 - i;
        {
            result.push(a[i]);
            i += 1;
        }

        // Second loop: copy all of `b`
        let n2 = b.len();
        let mut j: usize = 0;
        while j < n2
            invariant j <= n2;
            invariant result.len() == n1 + j;
            invariant forall(|k: usize| k < n1 ==> result[k] == a[k]);
            invariant forall(|k: usize| k < j ==> result[n1 + k] == b[k]);
            decreases n2 - j;
        {
            result.push(b[j]);
            j += 1;
        }

        result
    }

}